def shortest_path(graph, source, target):
    # Initialize the distance and path dictionaries
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Use a dictionary to keep track of the next node to visit
    next_node = {node: node for node in graph}

    while next_node[target] is not None:
        current_node = next_node[target]
        for neighbor, weight in graph[current_node]:
            if distances[current_node] + weight < distances[neighbor]:
                distances[neighbor] = distances[current_node] + weight
                path[neighbor] = current_node
                next_node[neighbor] = current_node
        next_node[current_node] = None
        for node in next_node:
            if next_node[node] is None:
                break
        else:
            # If all nodes have been exhausted, no path to target exists
            return float('inf'), None

    # Reconstruct the shortest path from target to source
    shortest_path = [target]
    while path[target] is not None:
        target = path[target]
        shortest_path.append(target)
    shortest_path.reverse()

    return distances[target], shortest_path

