from collections import deque

def shortest_path(graph, source, target):
    # If the graph is empty or the source is the target, no path is needed
    if not graph or source == target:
        return (0, [source])

    # Initialize the distance and path dictionaries
    distance = {node: float("inf") for node in graph}
    distance[source] = 0
    path = {node: None for node in graph}

    # Initialize the queue with the source node
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        # If we have reached the target node, we can return the path
        if current_node == target:
            path_list = deque()
            while current_node is not None:
                path_list.appendleft(current_node)
                current_node = path[current_node]
            return (current_distance, list(path_list))

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            new_distance = current_distance + weight
            if new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                path[neighbor] = current_node
                queue.append((neighbor, new_distance))

    # If we have exhausted the graph without finding the target, the target is unreachable
    return (float("inf"), None)

