def shortest_path(graph, source, target):
    # Build the graph in the form of a dictionary of dictionaries
    # where each key is a node and its value is another dictionary
    # mapping neighbors to their weights.
    def build_graph(graph_dict, edges):
        for src, dest, weight in edges:
            if src not in graph_dict:
                graph_dict[src] = {}
            if dest not in graph_dict:
                graph_dict[dest] = {}
            graph_dict[src][dest] = weight
            graph_dict[dest][src] = weight  # Graph is undirected

    def dijkstra(graph, source, target):
        # Priority queue with (cost, [path])
        priority_queue = [(0, [source])]
        visited = set()

        while priority_queue:
            (cost, path) = heapq.heappop(priority_queue)

            if path[-1] not in visited:
                visited.add(path[-1])

                if path[-1] == target:
                    return (cost, path)

                for neighbor in graph[path[-1]]:
                    if neighbor not in visited:
                        heapq.heappush(priority_queue, (cost + graph[path[-1]][neighbor], path + [neighbor]))

        return (float("inf"), None)

    # Build the graph
    build_graph(graph, edges)

    # Use Dijkstra's algorithm to find the shortest path
    return dijkstra(graph, source, target)

