def shortest_path(graph, source, target):
    def bellman_ford(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0

        for _ in range(len(graph) - 1):
            for node, neighbors in graph.items():
                for neighbor, weight in neighbors:
                    if distances[node] + weight < distances[neighbor]:
                        distances[neighbor] = distances[node] + weight

        for node, neighbors in graph.items():
            for neighbor, weight in neighbors:
                if distances[node] + weight < distances[neighbor]:
                    # Graph contains a negative weight cycle
                    return float('inf'), None

        return distances

    distances = bellman_ford(graph, source)

    if distances[target] == float('inf'):
        return float('inf'), None

    def reconstruct_path(graph, source, target, distances):
        path = [target]
        while source != target:
            for neighbor, weight in graph[path[-1]]:
                if distances[source] + weight == distances[neighbor] and neighbor != path[-1]:
                    path.insert(0, neighbor)
                    source = neighbor
                    break

        return path

    return (distances[target], reconstruct_path(graph, source, target, distances))
