def shortest_path(graph, source, target):
    from collections import defaultdict, deque
    import heapq

    # Helper function to get neighbors and their weights
    def get_neighbors(node):
        return [(neighbour, weight) for (neighbour, weight) in graph[node] if neighbour != source]

    # Dijkstra's algorithm
    def dijkstra(graph, start, end):
        distances = defaultdict(lambda: float('inf'))
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == end:
                return current_distance

            for neighbor, weight in get_neighbors(current_node):
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return float('inf')

    # Helper function to trace the path
    def trace_path(graph, source, target, parent):
        path = [target]
        while target != source:
            target = parent[target]
            path.append(target)
        path.reverse()
        return path

    # Track the shortest distance and path
    distance = dijkstra(graph, source, target)
    parent = defaultdict(lambda: None)

    for node in graph:
        for neighbor, _ in graph[node]:
            if distances[node] + neighbor == distances[neighbor]:
                parent[neighbor] = node

    if distance == float('inf'):
        return float('inf'), None
    else:
        return distance, trace_path(graph, source, target, parent)

