from collections import deque

def shortest_path(graph, source, target):
    def bfs(graph, source, target):
        if source == target:
            return [source], 0

        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = deque([(source, 0)])

        while queue:
            current_node, current_distance = queue.popleft()

            for neighbor, weight in graph.get(current_node, []):
                total_distance = current_distance + weight
                if total_distance < distances[neighbor]:
                    distances[neighbor] = total_distance
                    if neighbor == target:
                        path = [target]
                        while neighbor != source:
                            for n, w in graph.get(neighbor, []):
                                if w == distances[neighbor]:
                                    path.append(neighbor)
                                    neighbor = n
                                    break
                        path.reverse()
                        return (total_distance, path)
                    queue.append((neighbor, total_distance))

        if distances[target] == float('inf'):
            return float('inf'), None
        else:
            return (distances[target], None)

    return bfs(graph, source, target)

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

print(shortest_path(graph, 'A', 'D'))  # Example expected output: (6, ['A', 'C', 'D'])
print(shortest_path(graph, 'A', 'E'))  # Example expected output: (float('inf'), None)
